={{ JSON.stringify((() => {
  const text = (p) => ((p && (p.title || p.rich_text)) || []).map((t) => t.plain_text ?? (t.text && t.text.content) ?? '').join('');
  const pick = (p) => (p && p.select && p.select.name) || '';
  const day = (p) => (p && p.date && p.date.start) || '';
  const pages = $input.all().flatMap((item) => item.json.results || []);
  return { requests: pages.map((p) => ({
    url: p.url, request_id: text(p.properties['Request ID']), client: text(p.properties['Client']),
    platform: pick(p.properties['Platform']), status: pick(p.properties['Status']), priority: pick(p.properties['Priority']),
    publish_date: day(p.properties['Publish date']), review_requested: day(p.properties['Review requested']),
    requested_by: text(p.properties['Requested by']), notes: text(p.properties['Notes'])
  })) };
})()) }}

={{ JSON.stringify((() => {
  const today = $now.startOf('day');
  const soon = Number($env.URGENT_WITHIN_DAYS) || 2;
  const daysTo = (d) => d ? Math.round(DateTime.fromISO(d).startOf('day').diff(today, 'days').days) : null;
  const when = (n) => n === null ? 'no publish date' : n === -1 ? '1 day late' : n < 0 ? (-n) + ' days late' : n === 0 ? 'today' : n === 1 ? 'tomorrow' : 'in ' + n + ' days';
  const waited = (iso) => iso ? Math.max(0, Math.round($now.diff(DateTime.fromISO(iso), 'hours').hours)) + ' h' : 'unknown time';
  const ref = (r) => r.url ? '<' + r.url + '|' + r.request_id + '>' : r.request_id;
  const head = (r) => '• ' + r.client + ' · ' + r.platform + ' · ';
  const open = ['Drafting', 'In review', 'Needs attention', 'Failed'];
  const all = $json.requests.map((r) => Object.assign({}, r, { days: daysTo(r.publish_date) }));
  const urgent = all.filter((r) => open.includes(r.status) && r.days !== null && r.days <= soon).sort((a, b) => a.days - b.days);
  const rest = all.filter((r) => !urgent.includes(r));
  const review = rest.filter((r) => r.status === 'In review').sort((a, b) => String(a.review_requested).localeCompare(String(b.review_requested)));
  const attention = rest.filter((r) => r.status === 'Needs attention');
  const failed = rest.filter((r) => r.status === 'Failed');
  const week = all.filter((r) => r.status === 'Scheduled' && r.days !== null && r.days >= 0 && r.days <= 7);
  const section = (title, items, line) => items.length ? [title + ' (' + items.length + ')'].concat(items.map(line)).join('\n') : '';
  const pending = urgent.length + review.length + attention.length + failed.length;
  const parts = [
    '*Content digest* · ' + $now.toFormat('cccc d LLLL'),
    section('🔥 *Publishing soon, not scheduled yet*', urgent, (r) => head(r) + 'publishes ' + when(r.days) + ' · ' + r.status + (r.status === 'In review' ? ' for ' + waited(r.review_requested) : '') + ' · ' + r.requested_by + ' · ' + ref(r)),
    section('👀 *Waiting for review*', review, (r) => head(r) + 'waiting ' + waited(r.review_requested) + ' · publishes ' + when(r.days) + ' · ' + ref(r)),
    section('🙋 *Needs a person*', attention, (r) => head(r) + (r.notes || 'no reason given') + ' · ' + r.requested_by + ' · ' + ref(r)),
    section('🚨 *Failed*', failed, (r) => head(r) + (r.notes || 'no detail') + ' · ' + ref(r)),
    pending ? '' : 'Nothing is waiting on anyone. 🎉',
    '✅ Scheduled for the next 7 days: ' + week.length
  ].filter((p) => p);
  return { text: parts.join('\n\n'), counts: { urgent: urgent.length, review: review.length, attention: attention.length, failed: failed.length, scheduled_next_7_days: week.length } };
})()) }}
